'use strict';
(()=>{
 const alphabet=['∞','†','◉','⇡','▭','○','→','〰','✧','?','⊘','☲','∆','÷','≈','✛','⇤','≋','()','Y','≡'];
 const t={
 ca:{label:'Quin tema vols posar a debat?',placeholder:'Escriu un tema o una situació…',go:'Obrir el debat',wait:'Els símbols llegeixen el tema i preparen una escena…',error:'No s’ha pogut preparar el debat. Torna-ho a provar.',limit:'Has fet moltes proves seguides. Espera un minut.',invalid:'Escriu un tema entre 2 i 2.000 caràcters.',timeout:'El debat està trigant massa.',topic:'Tema',cast:'Mirades que entren al debat',emergence:'Les mirades juntes',open:'Mirada oberta',focusLabel:'Mirada concreta',continueLabel:'Per on vols continuar aquest debat?',thinking:'Una mirada obre una altra mirada…',continuePlaceholder:'Què voldries explorar ara?',continueGo:'Continuar el debat',panel:'El teu debat',panelNote:'Pots revisar el recorregut, desar-lo en PDF o esborrar-lo de la pantalla.',view:'Veure el recorregut',save:'Desar com a PDF',close:'Esborrar',confirm:'Vols tancar aquest debat i esborrar-lo de la pantalla? Desa el PDF abans si el vols conservar.',printTitle:'Debat d’Oraclia',printHint:'Al diàleg d’impressió, tria «Desar com a PDF».',printBlocked:'El navegador ha bloquejat la finestra d’impressió. Permet les finestres emergents i torna-ho a provar.'},
 es:{label:'¿Qué tema quieres poner a debate?',placeholder:'Escribe un tema o una situación…',go:'Abrir el debate',wait:'Los símbolos leen el tema y preparan una escena…',error:'No se ha podido preparar el debate. Vuelve a intentarlo.',limit:'Has hecho demasiadas pruebas seguidas. Espera un minuto.',invalid:'Escribe un tema de 2 a 2.000 caracteres.',timeout:'El debate está tardando demasiado.',topic:'Tema',cast:'Miradas que entran al debate',emergence:'Las miradas juntas',open:'Mirada abierta',focusLabel:'Mirada concreta',continueLabel:'¿Por dónde quieres continuar este debate?',thinking:'Una mirada abre otra mirada…',continuePlaceholder:'¿Qué quieres explorar ahora?',continueGo:'Continuar el debate',panel:'Tu debate',panelNote:'Puedes revisar el recorrido, guardarlo en PDF o borrarlo de la pantalla.',view:'Ver el recorrido',save:'Guardar como PDF',close:'Borrar',confirm:'¿Quieres cerrar este debate y borrarlo de la pantalla? Guarda el PDF antes si quieres conservarlo.',printTitle:'Debate de Oraclia',printHint:'En la ventana de impresión, elige «Guardar como PDF».',printBlocked:'El navegador ha bloqueado la ventana de impresión. Permite las ventanas emergentes e inténtalo de nuevo.'},
 en:{label:'What topic would you like to debate?',placeholder:'Write a topic or situation…',go:'Open the debate',wait:'The symbols are reading the topic and preparing a scene…',error:'Could not prepare the debate. Please try again.',limit:'Too many requests. Wait a minute.',invalid:'Enter a topic between 2 and 2,000 characters.',timeout:'The debate is taking too long.',topic:'Topic',cast:'Perspectives in the debate',emergence:'Perspectives together',open:'Open perspective',focusLabel:'Specific perspective',continueLabel:'Where would you like to take this debate next?',thinking:'One perspective opens another…',continuePlaceholder:'What would you like to explore?',continueGo:'Continue the debate',panel:'Your debate',panelNote:'Review the full debate, save it as a PDF or clear it from this page.',view:'View the full debate',save:'Save as PDF',close:'Clear',confirm:'Close this debate and clear it from the page? Save a PDF first if you want to keep it.',printTitle:'Oraclia debate',printHint:'In the print dialog, choose “Save as PDF”.',printBlocked:'Your browser blocked the print window. Allow pop-ups and try again.'}
 };
 const make=(tag,cls,txt)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(txt!==undefined)e.textContent=txt;return e;};
 document.querySelectorAll('[data-oraclia-debate]').forEach((root,i)=>{
  const lang=t[document.documentElement.lang]?document.documentElement.lang:'ca',v=t[lang];
  const form=make('form','debate-form'),label=make('label','',v.label),input=make('textarea'),go=make('button','debate-go',v.go),status=make('p','debate-status'),result=make('article','debate-result');
  input.id='debate-topic-'+i;label.htmlFor=input.id;input.required=true;input.minLength=2;input.maxLength=2000;input.rows=3;input.placeholder=v.placeholder;
  go.type='submit';result.hidden=true;result.setAttribute('aria-live','polite');status.setAttribute('role','status');
  form.append(label,input,go);root.replaceChildren(form,status,result);
  let busy=false,history=[],allDebates=[],nextFocus='',thinkingTimer=null;
  const actions=make('section','debate-export-actions'),panelTitle=make('h3','debate-export-title',v.panel),panelNote=make('p','debate-export-note',v.panelNote),buttons=make('div','debate-export-buttons'),view=make('button','debate-action-button',v.view),save=make('button','debate-action-button',v.save),close=make('button','debate-action-button',v.close);
  view.type='button';save.type='button';close.type='button';buttons.append(view,save,close);actions.append(panelTitle,panelNote,buttons);actions.hidden=true;root.append(actions);view.addEventListener('click',()=>{result.scrollIntoView({behavior:'smooth',block:'start'});});
  const esc=x=>String(x).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
  save.addEventListener('click',()=>{if(busy||!allDebates.length)return;const w=window.open('','_blank');if(!w){window.alert(v.printBlocked);return;}const parts=allDebates.map((d,j)=>`<section><h2>${j+1}. ${esc(d.title)}</h2><p class="scene">${esc(d.setting)}</p><p class="cast">${esc(v.cast)}: ${d.symbols.map(esc).join(' · ')}</p>${d.dialogue.map(turn=>`<div class="turn"><b>${esc(turn.speaker)}</b><p>${esc(turn.line)}</p></div>`).join('')}<div class="emergence"><h3>${esc(v.emergence)}</h3><p>${esc(d.emergence)}</p></div></section>`).join('');const html=`<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><title>${esc(v.printTitle)}</title><style>@page{size:A4;margin:18mm}body{font:12pt/1.55 Georgia,serif;color:#20231f;max-width:760px;margin:35px auto;padding:0 22px}h1{font-size:23pt}h2{font-size:17pt;margin-top:26px}h3{font-size:14pt}.scene{font-style:italic;color:#536358}.cast{font:10pt system-ui;color:#536358}.turn{display:flex;gap:14px;margin:14px 0;break-inside:avoid}.turn b{font-size:19pt;min-width:34px}.turn p{margin:0;white-space:pre-wrap}.emergence{border-top:1px solid #ccc;margin:22px 0;padding-top:12px;break-inside:avoid}section{border-top:1px solid #ddd;padding-top:12px}button{padding:10px 16px;margin:15px 0}@media print{button,.hint{display:none}body{margin:0;padding:0}}</style></head><body><h1>${esc(v.printTitle)}</h1><p><strong>${esc(v.topic)}:</strong> ${esc(input.value.trim())}</p>${parts}<p class="hint">${esc(v.printHint)}</p><button onclick="window.print()">${esc(v.save)}</button></body></html>`;w.document.open();w.document.write(html);w.document.close();w.focus();});
  close.addEventListener('click',()=>{if(busy||!allDebates.length||!window.confirm(v.confirm))return;stopThinking();history=[];allDebates=[];nextFocus='';input.value='';result.replaceChildren();result.hidden=true;status.textContent='';form.after(status);actions.hidden=true;input.focus();});
  const stopThinking=()=>{if(thinkingTimer!==null){clearInterval(thinkingTimer);thinkingTimer=null;}};
  const startThinking=()=>{stopThinking();const phrase=v.thinking;let n=0;status.textContent='';thinkingTimer=setInterval(()=>{n=Math.min(phrase.length,n+1);status.textContent=phrase.slice(0,n);if(n===phrase.length)stopThinking();},85);};
  input.addEventListener('input',()=>{history=[];allDebates=[];nextFocus='';result.hidden=true;result.replaceChildren();actions.hidden=true;status.textContent='';});
  form.addEventListener('submit',async e=>{
   e.preventDefault();if(busy)return;const topic=history.length?nextFocus:input.value.trim(),mode=history.length?'focus':'open',focus=history.length?nextFocus:null;if(topic.length<2||topic.length>2000){status.textContent=v.invalid;return;}
   busy=true;input.disabled=true;go.disabled=true;if(history.length){const currentFollow=result.querySelector('.debate-follow');if(currentFollow)currentFollow.after(status);}else{form.after(status);}startThinking();
   const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),120000);
   try{
    const response=await fetch((root.dataset.apiBase||'')+'/api/public/debate/generate',{method:'POST',credentials:'omit',signal:controller.signal,headers:{'Content-Type':'application/json','X-Library-Language':lang},body:JSON.stringify({topic,mode,focus,history})});
    const data=await response.json();if(!response.ok)throw Error(response.status===429?v.limit:v.error);
    if(data?.topic!==topic||!Array.isArray(data.symbols)||data.symbols.length<2||data.symbols.length>4||new Set(data.symbols).size!==data.symbols.length||data.symbols.some(g=>!alphabet.includes(g))||typeof data.title!=='string'||typeof data.setting!=='string'||!Array.isArray(data.dialogue)||data.dialogue.length<6||typeof data.emergence!=='string'||!data.emergence.trim())throw Error(v.error);
    const speakers=new Set(data.symbols);if(data.dialogue.some(x=>!speakers.has(x?.speaker)||typeof x.line!=='string'||!x.line.trim()))throw Error(v.error);
    result.querySelectorAll('.debate-follow').forEach(x=>x.remove());
    const heading=make('h4','debate-topic',data.title),scene=make('p','debate-setting',data.setting),cast=make('p','debate-cast',v.cast+': '+data.symbols.join(' · '));
    result.append(heading,scene,cast);
    for(const turn of data.dialogue){const row=make('div','debate-turn'),speaker=make('span','debate-speaker',turn.speaker),line=make('p','',turn.line);row.append(speaker,line);result.append(row);}
    const emergence=make('section','debate-emergence'),eh=make('h5','debate-emergence-title',v.emergence),ep=make('p','',data.emergence);emergence.append(eh,ep);result.append(emergence);
    allDebates.push({title:data.title,setting:data.setting,symbols:data.symbols,emergence:data.emergence,dialogue:data.dialogue});history.push({topic:data.topic,emergence:data.emergence,dialogue:data.dialogue});if(history.length>5)history.shift();
    const follow=make('form','debate-follow'),fl=make('label','',v.continueLabel),fi=make('textarea'),fb=make('button','debate-go',v.continueGo);
    fi.id='debate-follow-'+i;fl.htmlFor=fi.id;fi.rows=2;fi.minLength=2;fi.maxLength=300;fi.required=true;fi.placeholder=v.continuePlaceholder;fb.type='submit';
    follow.append(fl,fi,fb);follow.addEventListener('submit',ev=>{ev.preventDefault();if(busy)return;nextFocus=fi.value.trim();if(nextFocus.length<2||nextFocus.length>300){status.textContent=v.invalid;return;}form.requestSubmit();});
    result.append(follow);result.hidden=false;actions.hidden=false;root.append(actions);status.textContent='';
   }catch(err){stopThinking();status.textContent=err.name==='AbortError'?v.timeout:err.message||v.error;}
   finally{stopThinking();clearTimeout(timeout);busy=false;input.disabled=false;go.disabled=false;}
  });
 });
})();